function pick($where,$a=[],$n=8){$st=db()->prepare("SELECT p.*,s.name sub,s.slug subslug,t.name top FROM products p JOIN categories s ON s.id=p.category_id LEFT JOIN categories t ON t.id=s.parent_id WHERE p.status='active' AND $where ORDER BY RAND() LIMIT ".(int)$n);$st->execute($a);return $st->fetchAll();}
function card($p,$v=[]){$sale=(float)($p['old_price']??0)>(float)$p['base_price']&&$p['sold_by_type']!='variant';$out=$p['stock']<=0;$l=u_product($p);?><article class="card"><a class="im" href="<?=e($l)?>"><?=tile($p)?><?php if($sale): ?><span class="sb">Sale!</span><?php endif; ?><?php if($p['age_restricted']): ?><i>18+</i><?php endif; ?></a><div class="bd"><h2><a href="<?=e($l)?>"><?=e($p['name'])?></a></h2><div class="pr"><span class="p"><?=plabel($p)?></span></div>
<?php if($p['sold_by_type']=='variant'): ?><a class="add" href="<?=e($l)?>">Select options</a><?php else: ?><button class="add" data-sku="<?=e($p['sku'])?>" data-name="<?=e($p['name'])?>" data-step="<?=e($p['qty_step'])?>" <?=$out?'disabled':''?>><?=$out?'Out of stock':'Add to basket'?></button><?php endif; ?></div></article><?php }
function row($title,$rows,$link=''){if(!$rows)return;?><section class="sec rv"><div class="sh"><h2><?=e($title)?></h2><?php if($link): ?><a href="<?=e($link)?>">See all</a><?php endif; ?></div><div class="grid"><?php foreach($rows as $p)card($p); ?></div></section><?php }
function bankrows($b){$r=[['Bank',$b['bank'],0],['Account name',$b['name'],0],['Account number',$b['acc'],1],['Sort code',$b['sort'],1]];$h='<div class="bk">';
 foreach($r as $x)if(trim((string)$x[1])!=='')$h.='<div class="br"><span>'.e($x[0]).'</span><b>'.e($x[1]).'</b>'.($x[2]?'<button type="button" class="cp" data-copy="'.e(preg_replace('/\s+/','',$x[1])).'">Copy</button>':'').'</div>';
 return $h.($b['note']?'<p class="fine">'.e($b['note']).'</p>':'').'</div>';}
